   hypotenuse        → thick quad #00A79D + SphereGeometry endpoint dots
   red strip         → thin quad #F0534F
   block arrow       → ShapeGeometry ribbon, fill #FBE7C2, LineLoop outline #8C8C8C
   all text          → addLabel (HTML)
─────────────────────────────────────────────────────────────────────────── */

const C_FILL = 0xC7E6DF, C_TEAL = 0x00A79D, C_RED = 0xF0534F,
      C_CREAM = 0xFBE7C2, C_GRAY = 0x8C8C8C, C_BLACK = 0x000000;

const P = (x, y, z) => new THREE.Vector3(y, z, x);   // math → world

function fillMat(color, opacity) {
  return new THREE.MeshBasicMaterial({
    color, transparent: opacity < 1, opacity, side: THREE.DoubleSide, depthWrite: false
  });
}
function lineMat(color, opacity = 1) {
  return new THREE.LineBasicMaterial({ color, transparent: opacity < 1, opacity });
}
function triGeom(a, b, c) {
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.Float32BufferAttribute(
    [a, b, c].flatMap(v => [v.x, v.y, v.z]), 3));
  return g;
}
function quadGeom(a, b, c, dd) {
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.Float32BufferAttribute(
    [a, b, c, a, c, dd].flatMap(v => [v.x, v.y, v.z]), 3));
  return g;
}
function segGeom(p, q, w, perp) {
  const o = perp.clone().normalize().multiplyScalar(w / 2);
  return quadGeom(p.clone().add(o), q.clone().add(o), q.clone().sub(o), p.clone().sub(o));
}
function setGeom(mesh, g) { mesh.geometry.dispose(); mesh.geometry = g; }
function makeLine(pts, mat) { return new THREE.Line(new THREE.BufferGeometry().setFromPoints(pts), mat); }
function coneAt(tip, dir, color, len = 0.18, rad = 0.06) {
  const m = new THREE.Mesh(new THREE.ConeGeometry(rad, len, 20), new THREE.MeshBasicMaterial({ color }));
  const d = dir.clone().normalize();
  m.position.copy(tip).sub(d.clone().multiplyScalar(len / 2));
  m.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), d);
  return m;
}
function dotAt(p, color, r = 0.065) {
  const m = new THREE.Mesh(new THREE.SphereGeometry(r, 16, 12), new THREE.MeshBasicMaterial({ color }));
  m.position.copy(p);
  return m;
}

/* ══════════════ 3D PANEL ══════════════ */
const g3d = new THREE.Group();
scene.add(g3d);

const O = P(0, 0, 0), A = P(1, 0, 0), B = P(0, 2, 0), Cv = P(0, 0, 4);

function axis3(tipMath) {
  const tip = P(tipMath[0], tipMath[1], tipMath[2]);
  const dir = tip.clone().normalize();
  g3d.add(makeLine([O.clone(), tip.clone().sub(dir.clone().multiplyScalar(0.15))], lineMat(C_BLACK)));
  g3d.add(coneAt(tip, dir, C_BLACK));
}
axis3([1.45, 0, 0]);   // x toward viewer
axis3([0, 2.85, 0]);   // y to the right
axis3([0, 0, 4.8]);    // z up

// faces
const faceBase  = new THREE.Mesh(triGeom(O, A, B), fillMat(C_FILL, 0.78));
const faceSlant = new THREE.Mesh(triGeom(A, B, Cv), fillMat(C_FILL, 0.60));
const faceYZ    = new THREE.Mesh(triGeom(O, B, Cv), fillMat(C_FILL, 0.26));
const faceXZ    = new THREE.Mesh(triGeom(O, A, Cv), fillMat(C_FILL, 0.26));
g3d.add(faceBase, faceSlant, faceYZ, faceXZ);

// edges
g3d.add(makeLine([A, B], lineMat(C_TEAL, 0.9)));
g3d.add(makeLine([B, Cv], lineMat(C_TEAL, 0.9)));
g3d.add(makeLine([Cv, A], lineMat(C_TEAL, 0.9)));
g3d.add(makeLine([O, A], lineMat(0x8fbfb8, 0.9)));
g3d.add(makeLine([O, B], lineMat(0x8fbfb8, 0.9)));
g3d.add(makeLine([O, Cv], lineMat(0x8fbfb8, 0.9)));

// intercept dots
g3d.add(dotAt(A, C_TEAL), dotAt(B, C_TEAL), dotAt(Cv, C_TEAL));

// red strip in the xy-plane + vertical curtain
const strip3d   = new THREE.Mesh(new THREE.BufferGeometry(), fillMat(C_RED, 1));
const curtain3d = new THREE.Mesh(new THREE.BufferGeometry(), fillMat(C_RED, 0.22));
const curtainEdge = makeLine([O.clone(), O.clone(), O.clone()], lineMat(C_RED, 0.95));
g3d.add(strip3d, curtain3d, curtainEdge);

// slicing plane
const sliceGroup = new THREE.Group();
const slicePlane = new THREE.Mesh(new THREE.BufferGeometry(), fillMat(0x777777, 0.13));
const sliceTri   = new THREE.Mesh(new THREE.BufferGeometry(), fillMat(C_TEAL, 0.3));
const sliceEdge  = new THREE.Line(new THREE.BufferGeometry(), lineMat(0x00776f, 1));
sliceGroup.add(slicePlane, sliceTri, sliceEdge);
g3d.add(sliceGroup);

/* ══════════════ 2D INSET (billboard) ══════════════ */
const g2d = new THREE.Group();
g2d.position.set(2.6, 0.6, -1.2);
scene.add(g2d);

const V2 = (x, y) => new THREE.Vector3(x, y, 0);

function axis2(tip, dir) {
  g2d.add(makeLine([V2(dir.x < 0 ? 0 : -0.30 * Math.sign(dir.x || 1), 0).set(
    dir.x ? -0.30 : 0, dir.y ? -0.30 : 0, 0), tip.clone().sub(dir.clone().multiplyScalar(0.14))],
    lineMat(C_BLACK)));
  g2d.add(coneAt(tip, dir, C_BLACK, 0.16, 0.055));
}
axis2(V2(1.70, 0), new THREE.Vector3(1, 0, 0));
axis2(V2(0, 2.55), new THREE.Vector3(0, 1, 0));

g2d.add(new THREE.Mesh(triGeom(V2(0, 0), V2(1, 0), V2(0, 2)), fillMat(C_FILL, 0.85)));
g2d.add(new THREE.Mesh(segGeom(V2(0, 2), V2(1, 0), 0.045, new THREE.Vector3(2, 1, 0)),
  fillMat(C_TEAL, 1)));
g2d.add(dotAt(V2(0, 2), C_TEAL, 0.055), dotAt(V2(1, 0), C_TEAL, 0.055));

const strip2d = new THREE.Mesh(new THREE.BufferGeometry(), fillMat(C_RED, 1));
g2d.add(strip2d);

/* curved block arrow (local = screen plane) */
function ribbonArrow(ctrl, w, hw, hl) {
  const curve = new THREE.CatmullRomCurve3(ctrl.map(p => new THREE.Vector3(p[0], p[1], 0)));
  const N = 70;
  const pts = curve.getSpacedPoints(N);
  const total = curve.getLength();
  const bodyCount = Math.max(2, Math.floor(N * (1 - hl / total)));
  const body = pts.slice(0, bodyCount + 1);
  const tip = pts[N];
  const base = body[body.length - 1];
  const de = new THREE.Vector3().subVectors(tip, base).normalize();
  const ne = new THREE.Vector3(-de.y, de.x, 0);
  const left = [], right = [];
  for (let i = 0; i < body.length; i++) {
    const prev = body[Math.max(0, i - 1)], next = body[Math.min(body.length - 1, i + 1)];
    const t = new THREE.Vector3().subVectors(next, prev).normalize();
    const n = new THREE.Vector3(-t.y, t.x, 0).multiplyScalar(w / 2);
    left.push([body[i].x + n.x, body[i].y + n.y]);
    right.push([body[i].x - n.x, body[i].y - n.y]);
  }
  const s = new THREE.Shape();
  s.moveTo(left[0][0], left[0][1]);
  for (let i = 1; i < left.length; i++) s.lineTo(left[i][0], left[i][1]);
  s.lineTo(base.x + ne.x * hw / 2, base.y + ne.y * hw / 2);
  s.lineTo(tip.x, tip.y);
  s.lineTo(base.x - ne.x * hw / 2, base.y - ne.y * hw / 2);
  for (let i = right.length - 1; i >= 0; i--) s.lineTo(right[i][0], right[i][1]);
  s.closePath();
  return s;
}
const arrowShape = ribbonArrow(
  [[0.95, -0.45], [0.95, -1.15], [0.15, -1.55], [-1.35, -1.55], [-2.25, -1.20], [-2.52, -0.55]],
  0.25, 0.55, 0.40);
const gArrow = new THREE.Group();
gArrow.add(new THREE.Mesh(new THREE.ShapeGeometry(arrowShape), fillMat(C_CREAM, 1)));
gArrow.add(new THREE.LineLoop(new THREE.BufferGeometry().setFromPoints(
  arrowShape.getPoints().map(p => new THREE.Vector3(p.x, p.y, 0.001))), lineMat(C_GRAY, 1)));
g2d.add(gArrow);

/* ══════════════ dynamic geometry ══════════════ */
const state  = { panel: 'Both linked', stripX: 0.5, sliceHeight: 2 };
const target = { stripX: 0.5, sliceHeight: 2 };

function updateStrip() {
  const x = Math.min(0.995, Math.max(0.005, state.stripX));
  const h = 2 - 2 * x, top = 4 - 4 * x;
  // 2D
  setGeom(strip2d, segGeom(V2(x, 0), V2(x, h), 0.03, new THREE.Vector3(1, 0, 0)));
  // 3D base segment (lies in math z = 0)
  setGeom(strip3d, segGeom(P(x, 0, 0), P(x, h, 0), 0.03, new THREE.Vector3(0, 0, 1)));
  // 3D curtain triangle (x, 0,0)-(x,h,0)-(x,0,top)
  setGeom(curtain3d, triGeom(P(x, 0, 0), P(x, h, 0), P(x, 0, top)));
  setGeom(curtainEdge, new THREE.BufferGeometry().setFromPoints(
    [P(x, h, 0), P(x, 0, top), P(x, 0, 0)]));
  if (lblStripX) {
    lblStripX.local.set(x, -0.30, 0);
    lblStripX.entry.div.innerHTML = '<i>x</i> = ' + x.toFixed(2);
  }
}

function updateSlice() {
  const c = state.sliceHeight;
  const on = c < 3.97;
  sliceGroup.visible = on;
  if (!on) return;
  setGeom(slicePlane, quadGeom(P(0, 0, c), P(1.40, 0, c), P(1.40, 2.80, c), P(0, 2.80, c)));
  const a = (4 - c) / 4, b = (4 - c) / 2;
  setGeom(sliceTri, triGeom(P(0, 0, c), P(a, 0, c), P(0, b, c)));
  setGeom(sliceEdge, new THREE.BufferGeometry().setFromPoints(
    [P(0, 0, c), P(a, 0, c), P(0, b, c), P(0, 0, c)]));
  if (lblSlice) lblSlice.pos.copy(P(0, 2.85, c));
}

/* ══════════════ LABELS ══════════════ */
const labels3d = [];
const labels2d = [];
const F = { fontSize: '16px' };
function L3(t, p, o) { const e = addLabel(t, p, Object.assign({}, F, o || {})); labels3d.push(e); return e; }
function L2(t, lx, ly, o) {
  const e = addLabel(t, new THREE.Vector3(), Object.assign({}, F, o || {}));
  const rec = { entry: e, local: new THREE.Vector3(lx, ly, 0) };
  labels2d.push(rec); return rec;
}

L3('<i>z</i>', P(0, 0, 4.8), { offset: [16, -2] });
L3('<i>y</i>', P(0, 2.85, 0), { offset: [10, -16] });
L3('<i>x</i>', P(1.45, 0, 0), { offset: [-4, 20] });
L3('4', Cv, { offset: [-18, -2] });
L3('2', B, { offset: [4, -18] });
L3('1', A, { offset: [-20, 4] });
L3('<i>z</i> = 4 − 4<i>x</i> − 2<i>y</i>', P(0.2, 1.05, 2.65), { fontSize: '17px' });
L3('<i>R</i>', P(0.30, 0.50, 0.02), { fontSize: '17px' });
const lblSlice = L3('<i>z</i> = <i>c</i>', P(0, 2.85, 2), { color: '#00776f', fontSize: '14px' });

L2('<i>x</i>', 1.70, 0, { offset: [16, -12] });
L2('<i>y</i>', 0, 2.55, { offset: [14, -4] });
L2('0', -0.14, -0.05, { offset: [-6, 14] });
L2('1', 1.0, 0, { offset: [2, 18] });
L2('2', 0, 2.0, { offset: [-18, -2] });
L2('<i>R</i>', 0.22, 0.75, { fontSize: '17px' });
L2('<i>y</i> = 2 − 2<i>x</i>', 1.05, 1.35, { fontSize: '17px' });
const lblStripX = L2('<i>x</i> = 0.50', 0.5, -0.30, { color: '#c0322e', fontSize: '13px' });

/* ══════════════ INTERACTIVITY (hover / click) ══════════════ */
registerInteractive(faceSlant, {
  title: 'The plane z = 4 − 4x − 2y',
  tooltip: 'Top face: z = 4 − 4x − 2y',
  body: 'This slanted face is the graph of z = 4 − 4x − 2y over R. It meets the axes at x = 1, y = 2 and z = 4, and it is the integrand’s height above each point of R.'
});
registerInteractive(faceBase, {
  title: 'The region R',
  tooltip: 'Base region R in the xy-plane',
  body: 'R is the triangle with vertices (0,0), (1,0), (0,2), bounded by the axes and y = 2 − 2x. The volume is ∫∫_R (4 − 4x − 2y) dA = ∫₀¹∫₀^{2−2x}(4−4x−2y) dy dx = 4/3.'
});
registerInteractive(curtain3d, {
  title: 'Inner integration in y',
  tooltip: 'Slab over the red strip',
  body: 'At a fixed x the red strip runs from y = 0 to y = 2 − 2x. The slab above it has height z = 4 − 4x − 2y, giving the inner integral ∫₀^{2−2x}(4−4x−2y) dy.'
});

/* ══════════════ PANEL SWITCHING + CAMERA ══════════════ */
function applyPanel() {
  const show3 = state.panel !== '2D region R';
  const show2 = state.panel !== '3D tetrahedron';
  if (show3 && !g3d.parent) scene.add(g3d); if (!show3 && g3d.parent) scene.remove(g3d);
  if (show2 && !g2d.parent) scene.add(g2d); if (!show2 && g2d.parent) scene.remove(g2d);
  gArrow.visible = (state.panel === 'Both linked');
  g2d.quaternion.copy(camera.quaternion); g2d.updateMatrixWorld(true);
  setCameraView({ projection: 'orthographic', axisScreenAngles: { x: 30, z: 30 }, heightFraction: 0.7 });
  g2d.quaternion.copy(camera.quaternion); g2d.updateMatrixWorld(true);
  document.querySelectorAll('#panelBtns button').forEach(b =>
    b.classList.toggle('active', b.dataset.p === state.panel));
}

/* ══════════════ UI ══════════════ */
document.getElementById('btnReset').style.display = '';

const stripInput = document.getElementById('stripX');
const sliceInput = document.getElementById('sliceHeight');
const stripVal = document.getElementById('stripVal');
const sliceVal = document.getElementById('sliceVal');

stripInput.addEventListener('input', () => {
  state.stripX = target.stripX = parseFloat(stripInput.value);
  stripVal.textContent = state.stripX.toFixed(2);
  updateStrip();
});
sliceInput.addEventListener('input', () => {
  state.sliceHeight = target.sliceHeight = parseFloat(sliceInput.value);
  sliceVal.textContent = state.sliceHeight.toFixed(2);
  updateSlice();
});
document.querySelectorAll('#panelBtns button').forEach(b => {
  b.addEventListener('click', () => { state.panel = b.dataset.p; applyPanel(); });
});

const steps = [
  { title: 'The solid', narration: 'The tetrahedron is cut off from the first octant by the plane z = 4 − 4x − 2y, meeting the axes at x = 1, y = 2, z = 4. Orbit to see all four faces.',
    state: { panel: '3D tetrahedron', sliceHeight: 4, stripX: 0.5 } },
  { title: 'Project to the base', narration: 'Dropping the solid straight down gives the triangular region R in the xy-plane, bounded by the axes and the line y = 2 − 2x — exactly the inset panel.',
    state: { panel: 'Both linked', sliceHeight: 4, stripX: 0.5 } },
  { title: 'Inner integration in y', narration: 'Fix x and sweep the red strip: it always starts at y = 0 and stops on y = 2 − 2x, so the inner limits are 0 to 2 − 2x and the outer limits are x from 0 to 1.',
    state: { panel: '2D region R', sliceHeight: 4, stripX: 0.25 } },
  { title: 'Slicing by height', narration: 'Cut the tetrahedron with a horizontal plane: the cross-section stays a triangle with vertices on the edges, shrinking to a point as z → 4 — an alternate route to the same volume, 4/3.',
    state: { panel: '3D tetrahedron', sliceHeight: 2, stripX: 0.5 } }
];
let curStep = -1;
function goToStep(i) {
  curStep = (i + steps.length) % steps.length;
  const s = steps[curStep];
  document.getElementById('narrTitle').textContent = s.title;
  document.getElementById('narrText').textContent = s.narration;
  document.querySelectorAll('.stepBtn').forEach(b =>
    b.classList.toggle('active', +b.dataset.i === curStep));
  if (s.state.stripX !== undefined) target.stripX = s.state.stripX;
  if (s.state.sliceHeight !== undefined) target.sliceHeight = s.state.sliceHeight;
  if (s.state.panel && s.state.panel !== state.panel) { state.panel = s.state.panel; applyPanel(); }
}
document.querySelectorAll('.stepBtn').forEach(b =>
  b.addEventListener('click', () => goToStep(+b.dataset.i)));
document.getElementById('stepPrev').addEventListener('click', () => goToStep(curStep - 1));
document.getElementById('stepNext').addEventListener('click', () => goToStep(curStep + 1));

/* ══════════════ per-frame updates ══════════════ */
function syncUI() {
  stripInput.value = state.stripX.toFixed(3);
  stripVal.textContent = state.stripX.toFixed(2);
  sliceInput.value = state.sliceHeight.toFixed(2);
  sliceVal.textContent = state.sliceHeight.toFixed(2);
}
function tick() {
  requestAnimationFrame(tick);
  let changed = false;
  ['stripX', 'sliceHeight'].forEach(k => {
    const diff = target[k] - state[k];
    if (Math.abs(diff) > 1e-4) { state[k] += diff * 0.14; changed = true; }
    else if (state[k] !== target[k]) { state[k] = target[k]; changed = true; }
  });
  if (changed) { updateStrip(); updateSlice(); syncUI(); }

  g2d.quaternion.copy(camera.quaternion);
  g2d.updateMatrixWorld(true);
  for (const L of labels2d) L.entry.pos.copy(L.local).applyMatrix4(g2d.matrixWorld);

  const show3 = state.panel !== '2D region R';
  const show2 = state.panel !== '3D tetrahedron';
  for (const e of labels3d) e.div.style.visibility = show3 ? 'visible' : 'hidden';
  lblSlice.div.style.visibility = (show3 && sliceGroup.visible) ? 'visible' : 'hidden';
  for (const L of labels2d) L.entry.div.style.visibility = show2 ? 'visible' : 'hidden';
}

updateStrip();
updateSlice();
applyPanel();
goToStep(1);
state.stripX = target.stripX = 0.5;
state.sliceHeight = target.sliceHeight = 4;
updateStrip(); updateSlice(); syncUI();
tick();
// @FIGURE_CODE_END

