const C_FILL = 0xC7E6DF, C_TEAL = 0x00A79D, C_RED = 0xF0534F,
      C_CREAM = 0xFBE7C2, C_GRAY = 0x8C8C8C, C_BLACK = 0x000000;

const P = (x, y, z) => new THREE.Vector3(y, z, x);       // math → world
const MS = h => '<span style="font-family:\'Times New Roman\',Times,serif">' + h + '</span>';

let lblStripX = null, lblSlice = null;

function fillMat(color, opacity) {
  return new THREE.MeshBasicMaterial({
    color, transparent: opacity < 1, opacity, side: THREE.DoubleSide, depthWrite: false
  });
}
function lineMat(color, opacity = 1) {
  return new THREE.LineBasicMaterial({ color, transparent: opacity < 1, opacity });
}
function triGeom(a, b, c) {
