function ribbonArrow(ctrl, w, hw, hl) {
  const curve = new THREE.CatmullRomCurve3(ctrl.map(p => new THREE.Vector3(p[0], p[1], 0)),
    false, 'catmullrom', 0.4);
  const N = 80;
  const pts = curve.getSpacedPoints(N);
  const total = curve.getLength();
  const bodyCount = Math.max(2, Math.floor(N * (1 - hl / total)));
  const body = pts.slice(0, bodyCount + 1);
  const tip = pts[N];
  const base = body[body.length - 1];
  const de = new THREE.Vector3().subVectors(tip, base).normalize();
  const ne = new THREE.Vector3(-de.y, de.x, 0);
  const left = [], right = [];
  for (let i = 0; i < body.length; i++) {
    const prev = body[Math.max(0, i - 1)], next = body[Math.min(body.length - 1, i + 1)];
    const t = new THREE.Vector3().subVectors(next, prev).normalize();
    const n = new THREE.Vector3(-t.y, t.x, 0).multiplyScalar(w / 2);
    left.push([body[i].x + n.x, body[i].y + n.y]);
    right.push([body[i].x - n.x, body[i].y - n.y]);
  }
  const s = new THREE.Shape();
  s.moveTo(left[0][0], left[0][1]);
  for (let i = 1; i < left.length; i++) s.lineTo(left[i][0], left[i][1]);
  s.lineTo(base.x + ne.x * hw / 2, base.y + ne.y * hw / 2);
  s.lineTo(tip.x, tip.y);
  s.lineTo(base.x - ne.x * hw / 2, base.y - ne.y * hw / 2);
  for (let i = right.length - 1; i >= 0; i--) s.lineTo(right[i][0], right[i][1]);
  s.closePath();
  return s;
}
