// @FIGURE_CODE_BEGIN
/* ── ELEMENT SPEC ──────────────────────────────────────────────────────────
   math(x,y,z) → world (y, z, x)   [world Y is up]

   3D PANEL (group g3d — true 3D geometry, orbits)
   x/y/z axes          → Line black + ConeGeometry arrowheads (x→2.05, y→2.95, z→4.90)
   intercept dots      → SphereGeometry(0.075) teal #00A79D at (1,0,0),(0,2,0),(0,0,4)
   base face OAB       → triangle Mesh #C7E6DF op .82   (region R, z = 0)
   slant face ABC      → triangle Mesh #C7E6DF op .62   (z = 4−4x−2y)
   coord faces OBC,OAC → triangle Mesh #C7E6DF op .26
   edges               → Line teal (slant triangle) / pale teal (coordinate edges)
   red strip (3D)      → thick opaque quad in z=0, (x,0)→(x,2−2x), #EE2D24, depthTest off
   red slab (optional) → triangle Mesh #EE2D24 op .30 + outline — OFF by default
   slicing plane z=c   → quad Mesh grey op .13 + cross-section triangle + Line loop

   2D INSET (group g2d — billboarded, screen-locked right, scale 1.30, drawn on top)
   x/y axes            → Line black + cone arrowheads
   triangle R          → triangle Mesh #C7E6DF
   hypotenuse          → thick quad #00A79D + endpoint SphereGeometry dots
   red strip           → thick opaque quad #EE2D24, topmost renderOrder
   block arrow         → ShapeGeometry ribbon #FBE7C2 + LineLoop outline #8C8C8C
   all text            → addLabel (large serif/italic HTML)
─────────────────────────────────────────────────────────────────────────── */

const C_FILL = 0xC7E6DF, C_TEAL = 0x00A79D, C_RED = 0xEE2D24,
      C_CREAM = 0xFBE7C2, C_GRAY = 0x8C8C8C, C_BLACK = 0x000000;

const P = (x, y, z) => new THREE.Vector3(y, z, x);       // math → world
const MS = h => '<span style="font-family:\'Times New Roman\',Times,serif">' + h + '</span>';

let lblStripX = null, lblSlice = null;

function fillMat(color, opacity) {
  return new THREE.MeshBasicMaterial({
    color, transparent: opacity < 1, opacity, side: THREE.DoubleSide, depthWrite: false
  });
}
function lineMat(color, opacity = 1) {
  return new THREE.LineBasicMaterial({ color, transparent: opacity < 1, opacity });
}
function triGeom(a, b, c) {
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.Float32BufferAttribute(
    [a, b, c].flatMap(v => [v.x, v.y, v.z]), 3));
  return g;
}
function quadGeom(a, b, c, dd) {
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.Float32BufferAttribute(
    [a, b, c, a, c, dd].flatMap(v => [v.x, v.y, v.z]), 3));
  return g;
}
function segGeom(p, q, w, perp) {
  const o = perp.clone().normalize().multiplyScalar(w / 2);
  return quadGeom(p.clone().add(o), q.clone().add(o), q.clone().sub(o), p.clone().sub(o));
}
function setGeom(mesh, g) { mesh.geometry.dispose(); mesh.geometry = g; }
function makeLine(pts, mat) { return new THREE.Line(new THREE.BufferGeometry().setFromPoints(pts), mat); }
function coneAt(tip, dir, color, len = 0.22, rad = 0.075) {
  const m = new THREE.Mesh(new THREE.ConeGeometry(rad, len, 20), new THREE.MeshBasicMaterial({ color }));
  const d = dir.clone().normalize();
  m.position.copy(tip).sub(d.clone().multiplyScalar(len / 2));
  m.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), d);
  return m;
}
function dotAt(p, color, r = 0.075) {
  const m = new THREE.Mesh(new THREE.SphereGeometry(r, 18, 12), new THREE.MeshBasicMaterial({ color }));
  m.position.copy(p);
  return m;
}

/* ══════════════ 3D PANEL ══════════════ */
const g3d = new THREE.Group();
scene.add(g3d);

const O = P(0, 0, 0), A = P(1, 0, 0), B = P(0, 2, 0), Cv = P(0, 0, 4);

function axis3(tipMath) {
  const tip = P(tipMath[0], tipMath[1], tipMath[2]);
  const dir = tip.clone().normalize();
  g3d.add(makeLine([O.clone(), tip.clone().sub(dir.clone().multiplyScalar(0.18))], lineMat(C_BLACK)));
  g3d.add(coneAt(tip, dir, C_BLACK));
}
axis3([2.05, 0, 0]);   // x toward the viewer, down-left (well past the x = 1 intercept)
axis3([0, 2.95, 0]);   // y to the right
axis3([0, 0, 4.90]);   // z straight up

// faces
const faceBase  = new THREE.Mesh(triGeom(O, A, B), fillMat(C_FILL, 0.82));
const faceSlant = new THREE.Mesh(triGeom(A, B, Cv), fillMat(C_FILL, 0.62));
const faceYZ    = new THREE.Mesh(triGeom(O, B, Cv), fillMat(C_FILL, 0.26));
const faceXZ    = new THREE.Mesh(triGeom(O, A, Cv), fillMat(C_FILL, 0.26));
g3d.add(faceBase, faceSlant, faceYZ, faceXZ);

// edges
g3d.add(makeLine([A, B], lineMat(C_TEAL, 0.95)));
g3d.add(makeLine([B, Cv], lineMat(C_TEAL, 0.95)));
g3d.add(makeLine([Cv, A], lineMat(C_TEAL, 0.95)));
g3d.add(makeLine([O, A], lineMat(0x8fbfb8, 0.95)));
g3d.add(makeLine([O, B], lineMat(0x8fbfb8, 0.95)));
g3d.add(makeLine([O, Cv], lineMat(0x8fbfb8, 0.95)));

// intercept dots
g3d.add(dotAt(A, C_TEAL), dotAt(B, C_TEAL), dotAt(Cv, C_TEAL));

// red strip in the xy-plane (opaque, always on top of the pale base face)
const stripMat3 = fillMat(C_RED, 1);
stripMat3.depthTest = false;
const strip3d = new THREE.Mesh(new THREE.BufferGeometry(), stripMat3);
strip3d.renderOrder = 8;
g3d.add(strip3d);

// optional red slab (curtain) above the strip — hidden by default (not in the source figure)
const curtainGroup = new THREE.Group();
const curtain3d = new THREE.Mesh(new THREE.BufferGeometry(), fillMat(C_RED, 0.30));
curtain3d.renderOrder = 6;
const curtainEdge = makeLine([O.clone(), O.clone(), O.clone()], lineMat(C_RED, 0.95));
curtainEdge.renderOrder = 7;
curtainGroup.add(curtain3d, curtainEdge);

// slicing plane z = c
const sliceGroup = new THREE.Group();
const slicePlane = new THREE.Mesh(new THREE.BufferGeometry(), fillMat(0x777777, 0.13));
const sliceTri   = new THREE.Mesh(new THREE.BufferGeometry(), fillMat(C_TEAL, 0.35));
const sliceEdge  = new THREE.Line(new THREE.BufferGeometry(), lineMat(0x00776f, 1));
sliceGroup.add(slicePlane, sliceTri, sliceEdge);
g3d.add(sliceGroup);

/* ══════════════ 2D INSET (billboard, screen-locked right) ══════════════ */
const g2d = new THREE.Group();
g2d.scale.setScalar(1.30);
scene.add(g2d);

const INSET_RIGHT = 4.55, INSET_UP = 0.30;
const _camRight = new THREE.Vector3(), _camUp = new THREE.Vector3();
function updateInset() {
  camera.updateMatrixWorld();
  _camRight.setFromMatrixColumn(camera.matrixWorld, 0);
  _camUp.setFromMatrixColumn(camera.matrixWorld, 1);
  g2d.quaternion.copy(camera.quaternion);
  g2d.position.set(0, 0, 0)
    .addScaledVector(_camRight, INSET_RIGHT)
    .addScaledVector(_camUp, INSET_UP);
  g2d.updateMatrixWorld(true);
}

const V2 = (x, y) => new THREE.Vector3(x, y, 0);

function axis2(tail, tip) {
  const dir = tip.clone().sub(tail).normalize();
  g2d.add(makeLine([tail, tip.clone().sub(dir.clone().multiplyScalar(0.16))], lineMat(C_BLACK)));
  g2d.add(coneAt(tip, dir, C_BLACK, 0.19, 0.065));
}
axis2(V2(-0.36, 0), V2(1.70, 0));      // x axis
axis2(V2(0, -0.18), V2(0, 2.62));      // y axis

const tri2d = new THREE.Mesh(triGeom(V2(0, 0), V2(1, 0), V2(0, 2)), fillMat(C_FILL, 0.90));
g2d.add(tri2d);
const hyp2d = new THREE.Mesh(segGeom(V2(0, 2), V2(1, 0), 0.058, new THREE.Vector3(2, 1, 0)),
  fillMat(C_TEAL, 1));
g2d.add(hyp2d);
g2d.add(dotAt(V2(0, 2), C_TEAL, 0.070), dotAt(V2(1, 0), C_TEAL, 0.070));

const strip2d = new THREE.Mesh(new THREE.BufferGeometry(), fillMat(C_RED, 1));
strip2d.position.z = 0.01;
g2d.add(strip2d);

/* curved block arrow: tail at the 3D region R, head under the 2D panel pointing up */
function ribbonArrow(ctrl, w, hw, hl) {
  const curve = new THREE.CatmullRomCurve3(ctrl.map(p => new THREE.Vector3(p[0], p[1], 0)),
    false, 'catmullrom', 0.4);
  const N = 80;
  const pts = curve.getSpacedPoints(N);
  const total = curve.getLength();
  const bodyCount = Math.max(2, Math.floor(N * (1 - hl / total)));
  const body = pts.slice(0, bodyCount + 1);
  const tip = pts[N];
  const base = body[body.length - 1];
  const de = new THREE.Vector3().subVectors(tip, base).normalize();
  const ne = new THREE.Vector3(-de.y, de.x, 0);
  const left = [], right = [];
  for (let i = 0; i < body.length; i++) {
    const prev = body[Math.max(0, i - 1)], next = body[Math.min(body.length - 1, i + 1)];
    const t = new THREE.Vector3().subVectors(next, prev).normalize();
    const n = new THREE.Vector3(-t.y, t.x, 0).multiplyScalar(w / 2);
    left.push([body[i].x + n.x, body[i].y + n.y]);
    right.push([body[i].x - n.x, body[i].y - n.y]);
  }
  const s = new THREE.Shape();
  s.moveTo(left[0][0], left[0][1]);
  for (let i = 1; i < left.length; i++) s.lineTo(left[i][0], left[i][1]);
  s.lineTo(base.x + ne.x * hw / 2, base.y + ne.y * hw / 2);
  s.lineTo(tip.x, tip.y);
  s.lineTo(base.x - ne.x * hw / 2, base.y - ne.y * hw / 2);
  for (let i = right.length - 1; i >= 0; i--) s.lineTo(right[i][0], right[i][1]);
  s.closePath();
  return s;
}
const arrowShape = ribbonArrow(
  [[-3.05, -0.50], [-2.10, -0.95], [-0.95, -1.08], [0.15, -0.94], [0.58, -0.62], [0.58, -0.24]],
  0.34, 0.92, 0.46);
const gArrow = new THREE.Group();
const arrowFill = new THREE.Mesh(new THREE.ShapeGeometry(arrowShape), fillMat(C_CREAM, 1));
gArrow.add(arrowFill);
gArrow.add(new THREE.LineLoop(new THREE.BufferGeometry().setFromPoints(
  arrowShape.getPoints().map(p => new THREE.Vector3(p.x, p.y, 0.002))), lineMat(C_GRAY, 1)));
g2d.add(gArrow);

// the inset is an overlay: always draw it on top of the 3D panel
g2d.traverse(o => {
  o.renderOrder = 20;
  const ms = Array.isArray(o.material) ? o.material : (o.material ? [o.material] : []);
  ms.forEach(m => { m.depthTest = false; m.depthWrite = false; });
});
strip2d.renderOrder = 30;

/* ══════════════ dynamic geometry ══════════════ */
const state  = { panel: 'Both linked', stripX: 0.5, sliceHeight: 4, curtain: false };
const target = { stripX: 0.5, sliceHeight: 4 };

function updateStrip() {
  const x = Math.min(0.995, Math.max(0.005, state.stripX));
  const h = 2 - 2 * x, top = 4 - 4 * x;
  setGeom(strip2d, segGeom(V2(x, 0), V2(x, h), 0.050, new THREE.Vector3(1, 0, 0)));
  setGeom(strip3d, segGeom(P(x, 0, 0), P(x, h, 0), 0.060, new THREE.Vector3(0, 0, 1)));
  setGeom(curtain3d, triGeom(P(x, 0, 0), P(x, h, 0), P(x, 0, top)));
  setGeom(curtainEdge, new THREE.BufferGeometry().setFromPoints(
    [P(x, h, 0), P(x, 0, top), P(x, 0, 0)]));
  if (lblStripX) {
    lblStripX.local.set(x, -0.32, 0);
    lblStripX.entry.div.innerHTML = MS('<i>x</i> = ' + x.toFixed(2));
  }
}

function updateSlice() {
  const c = state.sliceHeight;
  const on = c < 3.97;
  sliceGroup.visible = on;
  if (!on) return;
  setGeom(slicePlane, quadGeom(P(0, 0, c), P(1.35, 0, c), P(1.35, 2.75, c), P(0, 2.75, c)));
  const a = (4 - c) / 4, b = (4 - c) / 2;
  setGeom(sliceTri, triGeom(P(0, 0, c), P(a, 0, c), P(0, b, c)));
  setGeom(sliceEdge, new THREE.BufferGeometry().setFromPoints(
    [P(0, 0, c), P(a, 0, c), P(0, b, c), P(0, 0, c)]));
  if (lblSlice) lblSlice.pos.copy(P(0, 2.95, c));
}

function applyCurtain() {
  if (state.curtain && !curtainGroup.parent) g3d.add(curtainGroup);
  if (!state.curtain && curtainGroup.parent) g3d.remove(curtainGroup);
  const cb = document.getElementById('showCurtain');
  if (cb) cb.checked = state.curtain;
}

/* ══════════════ LABELS ══════════════ */
const labels3d = [];
const labels2d = [];
function L3(t, p, o) {
  const e = addLabel(MS(t), p, Object.assign({ fontSize: '22px' }, o || {}));
  labels3d.push(e); return e;
}
function L2(t, lx, ly, o) {
  const e = addLabel(MS(t), new THREE.Vector3(), Object.assign({ fontSize: '22px' }, o || {}));
  const rec = { entry: e, local: new THREE.Vector3(lx, ly, 0) };
  labels2d.push(rec); return rec;
}

L3('<i>z</i>', P(0, 0, 4.90), { offset: [18, -6] });
L3('<i>y</i>', P(0, 2.95, 0), { offset: [14, -22] });
L3('<i>x</i>', P(2.05, 0, 0), { offset: [-10, 26] });
L3('4', Cv, { offset: [-24, 0] });
L3('2', B, { offset: [-6, -24] });
L3('1', A, { offset: [-26, 4] });
L3('<i>z</i> = 4 &minus; 4<i>x</i> &minus; 2<i>y</i>', P(0.15, 1.25, 2.60), { fontSize: '25px' });
L3('<i>R</i>', P(0.30, 0.52, 0.02), { fontSize: '25px' });
lblSlice = L3('<i>z</i> = <i>c</i>', P(0, 2.95, 2), { color: '#00776f', fontSize: '18px' });

L2('<i>x</i>', 1.70, 0, { offset: [20, -16] });
L2('<i>y</i>', 0, 2.62, { offset: [17, -8] });
L2('0', -0.22, 0, { offset: [-6, 20] });
L2('1', 1.0, 0, { offset: [4, 24] });
L2('2', 0, 2.0, { offset: [-24, -2] });
L2('<i>R</i>', 0.24, 0.76, { fontSize: '25px' });
L2('<i>y</i> = 2 &minus; 2<i>x</i>', 1.05, 1.46, { fontSize: '25px' });
lblStripX = L2('<i>x</i> = 0.50', 0.5, -0.32, { color: '#c0322e', fontSize: '16px' });

/* ══════════════ hover / click explanations ══════════════ */
registerInteractive(faceSlant, {
  title: 'The plane z = 4 − 4x − 2y',
  tooltip: 'Top face: z = 4 − 4x − 2y',
