/* ══════════════ panel switching + camera ══════════════ */
const VIEW = { projection: 'orthographic', axisScreenAngles: { x: 6, z: 52 }, heightFraction: 0.92 };

function applyPanel() {
  const show3 = state.panel !== '2D region R';
  const show2 = state.panel !== '3D tetrahedron';
  if (show3 && !g3d.parent) scene.add(g3d);
  if (!show3 && g3d.parent) scene.remove(g3d);
  if (show2 && !g2d.parent) scene.add(g2d);
  if (!show2 && g2d.parent) scene.remove(g2d);
  gArrow.visible = (state.panel === 'Both linked');
  updateInset();
  setCameraView(VIEW);   // settle the pose
  updateInset();         // place the overlay for that pose
  setCameraView(VIEW);   // re-fit with the overlay in its final spot
  document.querySelectorAll('#panelBtns button').forEach(b =>
    b.classList.toggle('active', b.dataset.p === state.panel));
}

/* ══════════════ UI ══════════════ */
document.getElementById('btnReset').style.display = '';

const stripInput = document.getElementById('stripX');
const sliceInput = document.getElementById('sliceHeight');
const stripVal = document.getElementById('stripVal');
const sliceVal = document.getElementById('sliceVal');
const curtainBox = document.getElementById('showCurtain');

stripInput.addEventListener('input', () => {
  state.stripX = target.stripX = parseFloat(stripInput.value);
  stripVal.textContent = state.stripX.toFixed(2);
  updateStrip();
});
sliceInput.addEventListener('input', () => {
  state.sliceHeight = target.sliceHeight = parseFloat(sliceInput.value);
  sliceVal.textContent = state.sliceHeight.toFixed(2);
  updateSlice();
});
curtainBox.addEventListener('change', () => {
  state.curtain = curtainBox.checked;
  applyCurtain();
});
document.querySelectorAll('#panelBtns button').forEach(b => {
  b.addEventListener('click', () => { state.panel = b.dataset.p; applyPanel(); });
});

const steps = [
  { title: 'The solid',
    narration: 'The tetrahedron is cut off from the first octant by the plane z = 4 − 4x − 2y, meeting the axes at x = 1, y = 2, z = 4. Orbit to see all four faces.',
    state: { panel: '3D tetrahedron', sliceHeight: 4, stripX: 0.5, curtain: false } },
  { title: 'Project to the base',
    narration: 'Dropping the solid straight down gives the triangular region R in the xy-plane, bounded by the axes and the line y = 2 − 2x — exactly the inset panel the block arrow points to.',
    state: { panel: 'Both linked', sliceHeight: 4, stripX: 0.5, curtain: false } },
  { title: 'Inner integration in y',
    narration: 'Fix x and sweep the red strip: it always starts at y = 0 and stops on y = 2 − 2x, so the inner limits are 0 to 2 − 2x and the outer limits are x from 0 to 1. The slab standing on the strip is capped by z = 4 − 4x − 2y.',
    state: { panel: 'Both linked', sliceHeight: 4, stripX: 0.25, curtain: true } },
  { title: 'Slicing by height',
    narration: 'Cut the tetrahedron with a horizontal plane: the cross-section stays a triangle with vertices on the edges, shrinking to a point as z → 4 — an alternate route to the same volume, 4/3.',
    state: { panel: '3D tetrahedron', sliceHeight: 2, stripX: 0.5, curtain: false } }
];
let curStep = -1;
function goToStep(i) {
  curStep = (i + steps.length) % steps.length;
  const s = steps[curStep];
  document.getElementById('narrTitle').textContent = s.title;
  document.getElementById('narrText').textContent = s.narration;
  document.querySelectorAll('.stepBtn').forEach(b =>
    b.classList.toggle('active', +b.dataset.i === curStep));
  if (s.state.stripX !== undefined) target.stripX = s.state.stripX;
  if (s.state.sliceHeight !== undefined) target.sliceHeight = s.state.sliceHeight;
  if (s.state.curtain !== undefined) { state.curtain = s.state.curtain; applyCurtain(); }
  if (s.state.panel && s.state.panel !== state.panel) { state.panel = s.state.panel; applyPanel(); }
}
document.querySelectorAll('.stepBtn').forEach(b =>
  b.addEventListener('click', () => goToStep(+b.dataset.i)));
document.getElementById('stepPrev').addEventListener('click', () => goToStep(curStep - 1));
document.getElementById('stepNext').addEventListener('click', () => goToStep(curStep + 1));

/* ══════════════ per-frame updates ══════════════ */
function syncUI() {
  stripInput.value = state.stripX.toFixed(3);
  stripVal.textContent = state.stripX.toFixed(2);
  sliceInput.value = state.sliceHeight.toFixed(2);
  sliceVal.textContent = state.sliceHeight.toFixed(2);
}
function tick() {
  requestAnimationFrame(tick);
  let changed = false;
  ['stripX', 'sliceHeight'].forEach(k => {
    const diff = target[k] - state[k];
    if (Math.abs(diff) > 1e-4) { state[k] += diff * 0.14; changed = true; }
    else if (state[k] !== target[k]) { state[k] = target[k]; changed = true; }
  });
  if (changed) { updateStrip(); updateSlice(); syncUI(); }

  updateInset();
  for (const L of labels2d) L.entry.pos.copy(L.local).applyMatrix4(g2d.matrixWorld);

  const show3 = state.panel !== '2D region R';
  const show2 = state.panel !== '3D tetrahedron';
  for (const e of labels3d) e.div.style.visibility = show3 ? 'visible' : 'hidden';
  lblSlice.div.style.visibility = (show3 && sliceGroup.visible) ? 'visible' : 'hidden';
  for (const L of labels2d) L.entry.div.style.visibility = show2 ? 'visible' : 'hidden';
}

updateStrip();
updateSlice();
applyCurtain();
goToStep(1);                       // open on the source figure's "both panels" view
state.stripX = target.stripX = 0.5;
state.sliceHeight = target.sliceHeight = 4;
updateStrip(); updateSlice(); syncUI();
applyPanel();
tick();
